declare function retryLite<A>(
  fn: retryLite.RetryFunction<A>,
  opts: retryLite.Options
): Promise<A>;

declare namespace retryLite {
  interface Options {
    retries?: number;
    onRetry?: (e: Error) => any;
  }

  type RetryFunction<A> = (bail: (e: Error) => void, attempt: number) => A | Promise<A>;
}

export = retryLite;
